// Cloudflare Worker entry: the generated OpenNext handler, with headers that
// name the API's hosting provider removed from every response.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";
import { withoutHostingHeaders } from "./lib/response-headers";

export default {
  async fetch(request: Request, env: unknown, ctx: unknown) {
    return withoutHostingHeaders(await handler.fetch(request, env, ctx));
  },
};
